@Test
@OverwriteProp.OverwriteProps({ //
//
@OverwriteProp(key = "kylin.metadata.url", value = "test@jdbc,driverClassName=org.h2.Driver,url=jdbc:h2:mem:db_default;DB_CLOSE_DELAY=-1;MODE=MYSQL,username=sa,password=") })
public void testAuditLogOutOfOrder() throws Exception {
    val listener = new StatusListener();
    EventBusFactory.getInstance().register(listener, true);
    val systemStore = ResourceStore.getKylinMetaStore(getTestConfig());
    val auditLogStore = (JdbcAuditLogStore) systemStore.getAuditLogStore();
    UnitOfWork.doInTransactionWithRetry(() -> {
        val store = ResourceStore.getKylinMetaStore(KylinConfig.getInstanceFromEnv());
        UnitOfWork.get().getCopyForWriteItems().add("PROJECT/a");
        store.checkAndPutResource("PROJECT/a", new StringEntity("a", RandomUtil.randomUUIDStr()), StringEntity.serializer);
        return null;
    }, "a");
    UnitOfWork.doInTransactionWithRetry(() -> {
        val store = ResourceStore.getKylinMetaStore(KylinConfig.getInstanceFromEnv());
        UnitOfWork.get().getCopyForWriteItems().add("PROJECT/b");
        store.checkAndPutResource("PROJECT/b", new StringEntity("b", RandomUtil.randomUUIDStr()), StringEntity.serializer);
        return null;
    }, "b");
    Assert.assertEquals(2, systemStore.listResourcesRecursively(ALL.name()).size());
    Thread t = new Thread(() -> {
        val t1 = new Thread(() -> {
            UnitOfWork.doInTransactionWithRetry(() -> {
                Thread.sleep(500);
                val store = ResourceStore.getKylinMetaStore(KylinConfig.getInstanceFromEnv());
                val path = "PROJECT/a-" + System.currentTimeMillis();
                UnitOfWork.get().getCopyForWriteItems().add(path);
                val originAbc = store.getResource(path, true);
                store.checkAndPutResource(path, RawResourceTool.createByteSourceByPath(path), System.currentTimeMillis(), originAbc == null ? -1 : originAbc.getMvcc());
                return 0;
            }, "a");
            try {
                auditLogStore.catchupWithTimeout();
            } catch (Exception e) {
                log.error("catchup 1st phase failed", e);
            }
        });
        t1.start();
        Map<String, Long> versions = Maps.newHashMap();
        int size = 200;
        MetadataStore metadataStore = systemStore.getMetadataStore();
        IntStream.range(1000, 1000 + size).forEach(id -> {
            String metaKey = "b-" + id;
            String path = "PROJECT/b-" + id;
            RawResource result = systemStore.getResource(path, true);
            val newMvcc = result == null ? 0 : result.getMvcc() + 1;
            // When newMvcc is 0, do not record auditLog, so that the subsequent catchupWithTimeout error
            if (newMvcc == 0) {
                metadataStore.save(MetadataType.PROJECT, RawResourceTool.createProjectRawResource(metaKey, newMvcc));
            } else {
                metadataStore.save(MetadataType.PROJECT, RawResourceTool.createProjectRawResource(metaKey, newMvcc));
                List<Event> events = Collections.singletonList(new ResourceCreateOrUpdateEvent(path, new RawResource(metaKey, RawResourceTool.createByteSource(metaKey), System.currentTimeMillis(), newMvcc)));
                val unitMessages = new UnitMessages(events);
                metadataStore.getAuditLogStore().save(unitMessages);
                versions.put(path, newMvcc);
            }
        });
        try {
            t1.join();
            Thread.sleep(1000);
        } catch (InterruptedException e) {
            log.debug("wait for thread join failed", e);
        }
        try {
            auditLogStore.catchupWithTimeout();
        } catch (Exception e) {
            log.error("catchup 2nd phase failed", e);
        }
        try {
            UnitOfWork.doInTransactionWithRetry(() -> {
                val store = ResourceStore.getKylinMetaStore(KylinConfig.getInstanceFromEnv());
                IntStream.range(1000, 1000 + size).forEach(id -> {
                    String path = "PROJECT/b-" + id;
                    UnitOfWork.get().getCopyForWriteItems().add(path);
                    val originAbc = store.getResource(path, true);
                    store.checkAndPutResource(path, RawResourceTool.createByteSourceByPath(path + "-version2"), System.currentTimeMillis(), originAbc == null ? -1 : originAbc.getMvcc());
                });
                return 0;
            }, "b");
            auditLogStore.catchupWithTimeout();
        } catch (Exception e) {
            log.error("catchup 3rd phase failed", e);
        }
    });
    t.start();
    // reload is triggered, onEnd is called, and the status becomes -1
    Awaitility.await().atMost(200, TimeUnit.SECONDS).until(() -> listener.status == -1);
    // AuditLog store is skipped, the jsonPath error is reported, and the save fails, so there are only 2
    Assert.assertEquals(203, systemStore.listResourcesRecursively(ALL.name()).size());
    t.join();
}

@Test
public void testPathFilter() {
    RawResourceFilter rawResourceFilter = new RawResourceFilter();
    rawResourceFilter.addConditions(new RawResourceFilter.Condition("metaKey", Collections.singletonList("DEFAULT.TEST_KYLIN_FACT"), EQUAL));
    var context = convertConditionsToFilter(rawResourceFilter, MetadataType.TABLE_INFO);
    String resPath = context.getResPath();
    var regex = context.getRegex();
    var jsonFilter = context.getRawResourceFilter();
    boolean isWholePath = context.isWholePath();
    Assert.assertEquals("TABLE_INFO/DEFAULT.TEST_KYLIN_FACT.json", resPath);
    Assert.assertNull(regex);
    Assertions.assertThat(jsonFilter.getConditions().isEmpty()).isTrue();
    Assert.assertTrue(isWholePath);
    // '>' and '<' Operator
    rawResourceFilter = RawResourceFilter.simpleFilter(RawResourceFilter.Operator.GT, "createTime", "1604288097900");
    context = convertConditionsToFilter(rawResourceFilter, MetadataType.TABLE_INFO);
    resPath = context.getResPath();
    regex = context.getRegex();
    jsonFilter = context.getRawResourceFilter();
    isWholePath = context.isWholePath();
    Assert.assertEquals("TABLE_INFO", resPath);
    Assert.assertNull(regex);
    Assertions.assertThat(jsonFilter.getConditions().size()).isSameAs(1);
    Assert.assertFalse(isWholePath);
}

@Test
public void testRegexTablePathFilter() {
    UnitOfWork.doInTransactionWithRetry(() -> {
        UnitOfWork.get().getCopyForWriteItems().add("TABLE_INFO/pj1.db.abc2");
        val store1 = ResourceStore.getKylinMetaStore(KylinConfig.getInstanceFromEnv());
        String uuid = UUID.randomUUID().toString();
        store1.checkAndPutResource("TABLE_INFO/pj1.db.abc2", ByteSource.wrap(("{ \"uuid\" : \"" + uuid + "\",\"meta_key\" : \"pj1.db.abc2\",\"name\" : \"abc2\", \"project\" : \"pj1\",\"database\"" + " : \"db\", \"id\" : \"20002\" }").getBytes(DEFAULT_CHARSET)), -1);
        return 0;
    }, "pj1");
    UnitOfWork.doInTransactionWithRetry(() -> {
        val store1 = ResourceStore.getKylinMetaStore(KylinConfig.getInstanceFromEnv());
        RawResourceFilter filter = new RawResourceFilter();
        filter.addConditions(new RawResourceFilter.Condition("name", Collections.singletonList("abc2"), EQUAL));
        List<RawResource> tableInfo = store1.getMatchedResourcesWithoutContent("TABLE_INFO", filter);
        checkTable(tableInfo);
        RawResourceFilter filter2 = new RawResourceFilter();
        filter2.addConditions(new RawResourceFilter.Condition("name", Collections.singletonList("ABC2"), RawResourceFilter.Operator.EQUAL_CASE_INSENSITIVE));
        tableInfo = store1.getMatchedResourcesWithoutContent("TABLE_INFO", filter2);
        checkTable(tableInfo);
        RawResourceFilter filter3 = new RawResourceFilter();
        filter3.addConditions(new RawResourceFilter.Condition("name", Collections.singletonList("B1C"), RawResourceFilter.Operator.LIKE_CASE_INSENSITIVE));
        tableInfo = store1.getMatchedResourcesWithoutContent("TABLE_INFO", filter3);
        Assert.assertEquals(0, tableInfo.size());
        RawResourceFilter filter4 = new RawResourceFilter();
        filter4.addConditions("dbName", Arrays.asList("db.xxx", "db"), RawResourceFilter.Operator.IN).addConditions("name", Arrays.asList("abc2", "xxx"), RawResourceFilter.Operator.IN);
        tableInfo = store1.getMatchedResourcesWithoutContent("TABLE_INFO", filter4);
        checkTable(tableInfo);
        // '>' and '<' Operator
        RawResourceFilter filter5 = RawResourceFilter.simpleFilter(RawResourceFilter.Operator.GT, "createTime", "1604288097900");
        store1.getMatchedResourcesWithoutContent("HISTORY_SOURCE_USAGE", filter5);
        RawResourceFilter filter6 = new RawResourceFilter();
        filter6.addConditions("dbName", Collections.singletonList("D"), RawResourceFilter.Operator.LIKE_CASE_INSENSITIVE).addConditions("name", Collections.singletonList("c2"), RawResourceFilter.Operator.LIKE_CASE_INSENSITIVE);
        var context = convertConditionsToFilter(filter6, MetadataType.TABLE_INFO);
        Assert.assertEquals("TABLE_INFO", context.getResPath());
        tableInfo = store1.getMatchedResourcesWithoutContent("TABLE_INFO", filter6);
        checkTable(tableInfo);
        RawResourceFilter filter7 = new RawResourceFilter();
        filter7.addConditions(new RawResourceFilter.Condition("metaKey", Collections.singletonList("pj1.db.abc2"), EQUAL));
        context = convertConditionsToFilter(filter7, MetadataType.TABLE_INFO);
        Assert.assertEquals("TABLE_INFO/pj1.db.abc2.json", context.getResPath());
        tableInfo = store1.getMatchedResourcesWithoutContent("TABLE_INFO", filter7);
        checkTable(tableInfo);
        RawResourceFilter filter8 = new RawResourceFilter();
        filter8.addConditions(new RawResourceFilter.Condition("metaKey", Collections.singletonList("pj1.DB"), RawResourceFilter.Operator.LIKE_CASE_INSENSITIVE));
        context = convertConditionsToFilter(filter8, MetadataType.TABLE_INFO);
        Assert.assertEquals("(?i).*\\Qpj1.DB\\E.*", context.getRegex());
        Assert.assertEquals("TABLE_INFO", context.getResPath());
        tableInfo = store1.getMatchedResourcesWithoutContent("TABLE_INFO", filter8);
        checkTable(tableInfo);
        // case insensitive
        RawResourceFilter filter9 = new RawResourceFilter();
        filter9.addConditions(new RawResourceFilter.Condition("metaKey", Collections.singletonList("pj1.db.ABC2"), RawResourceFilter.Operator.EQUAL_CASE_INSENSITIVE));
        context = convertConditionsToFilter(filter9, MetadataType.TABLE_INFO);
        Assert.assertEquals("(?i)\\Qpj1.db.ABC2.json\\E", context.getRegex());
        Assert.assertEquals("TABLE_INFO", context.getResPath());
        tableInfo = store1.getMatchedResourcesWithoutContent("TABLE_INFO", filter9);
        checkTable(tableInfo);
        // IN Operator
        RawResourceFilter filter10 = new RawResourceFilter();
        filter10.addConditions(new RawResourceFilter.Condition("metaKey", Arrays.asList("pj1.db.abc2", "123", "321"), RawResourceFilter.Operator.IN));
        context = convertConditionsToFilter(filter10, MetadataType.TABLE_INFO);
        Assert.assertEquals("\\Qpj1.db.abc2.json\\E|\\Q123.json\\E|\\Q321.json\\E", context.getRegex());
        Assert.assertEquals("TABLE_INFO", context.getResPath());
        tableInfo = store1.getMatchedResourcesWithoutContent("TABLE_INFO", filter10);
        checkTable(tableInfo);
        // in case of empty values
        RawResourceFilter filter11 = new RawResourceFilter();
        filter11.addConditions(new RawResourceFilter.Condition("metaKey", Collections.emptyList(), RawResourceFilter.Operator.IN));
        context = convertConditionsToFilter(filter11, MetadataType.TABLE_INFO);
        Assert.assertEquals("", context.getRegex());
        Assert.assertEquals("TABLE_INFO", context.getResPath());
        tableInfo = store1.getMatchedResourcesWithoutContent("TABLE_INFO", filter11);
        Assert.assertEquals(0, tableInfo.size());
        // in case of empty values
        RawResourceFilter filter12 = new RawResourceFilter();
        filter12.addConditions(new RawResourceFilter.Condition("metaKey", Arrays.asList("pj1.db.", "123"), RawResourceFilter.Operator.IN));
        context = convertConditionsToFilter(filter12, MetadataType.TABLE_INFO);
        Assert.assertEquals("\\Qpj1.db..json\\E|\\Q123.json\\E", context.getRegex());
        Assert.assertEquals("TABLE_INFO", context.getResPath());
        tableInfo = store1.getMatchedResourcesWithoutContent("TABLE_INFO", filter12);
        Assert.assertEquals(0, tableInfo.size());
        return 0;
    }, "pj1");
}

