    val workerStore = ResourceStore.getKylinMetaStore(getTestConfig());
    workerStore.checkAndPutResource(ResourceStore.METASTORE_UUID_TAG, new StringEntity(RandomUtil.randomUUIDStr()), StringEntity.serializer);
