@Test
void testWriteLockExclusive() {
    Object condition = new Object();
    AtomicBoolean stop = new AtomicBoolean();
    Thread writeLockHelder = new Thread(() -> {
        UnitOfWork.doInTransactionWithRetry(UnitOfWorkParams.builder().unitName(UnitOfWork.GLOBAL_UNIT).maxRetry(1).processor(() -> {
            val resourceStoreInTransaction = ResourceStore.getKylinMetaStore(KylinConfig.getInstanceFromEnv());
            System.out.println("Write thread start to lock");
            String resPath = "PROJECT/res1";
            UnitOfWork.get().getCopyForWriteItems().add(resPath);
            resourceStoreInTransaction.getResource(resPath, true);
            resourceStoreInTransaction.checkAndPutResource(resPath, ByteSource.wrap("{}".getBytes(Charset.defaultCharset())), -1L);
            synchronized (condition) {
                condition.notify();
            }
            boolean interrupted = false;
            while (!interrupted && !Thread.interrupted() && !stop.get()) {
                synchronized (condition) {
                    condition.notify();
                }
                try {
                    Thread.sleep(1000);
                } catch (InterruptedException e) {
                    interrupted = true;
                }
            }
            synchronized (condition) {
                condition.notify();
            }
            System.out.println("Write thread finished.");
            return 0;
        }).build());
    });
    writeLockHelder.start();
    synchronized (condition) {
        try {
            condition.wait();
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
    }
    new Thread(() -> {
        try {
            Thread.sleep(2000);
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
        stop.set(true);
    }).start();
    long start = System.currentTimeMillis();
    UnitOfWork.doInTransactionWithRetry(//
    UnitOfWorkParams.builder().unitName(UnitOfWork.GLOBAL_UNIT).maxRetry(1).processor(() -> {
        System.out.println("Read thread start to lock.");
        RawResource raw = ResourceStore.getKylinMetaStore(KylinConfig.getInstanceFromEnv()).getResource("PROJECT/res1", true);
        System.out.println("Read thread lock succeed.");
        long cost = System.currentTimeMillis() - start;
        System.out.println("Read thread cost " + cost + "ms, mvcc:" + (raw == null ? -2 : raw.getMvcc()));
        assert raw != null;
        Assertions.assertEquals(0, raw.getMvcc());
        return 0;
    }).build());
    stop.set(true);
}

