@Test
public void testGetOutputFromHDFSByJobId() throws IOException {
    File file = temporaryFolder.newFile("execute_output.json." + System.currentTimeMillis() + ".log");
    for (int i = 0; i < 200; i++) {
        Files.write(file.toPath(), String.format(Locale.ROOT, "lines: %s\n", i).getBytes(Charset.defaultCharset()), StandardOpenOption.APPEND);
    }
    String[] exceptLines = Files.readAllLines(file.toPath()).toArray(new String[0]);
    ExecutableManager manager = executableManager;
    ExecutableOutputPO executableOutputPO = new ExecutableOutputPO();
    executableOutputPO.setStatus("SUCCEED");
    executableOutputPO.setContent("succeed");
    executableOutputPO.setLogPath(file.getAbsolutePath());
    manager.updateJobOutputToHDFS(KylinConfig.getInstanceFromEnv().getJobTmpOutputStorePath("default", "e1ad7bb0-522e-456a-859d-2eab1df448de"), executableOutputPO);
    String sampleLog = "";
    try (InputStream verboseMsgStream = executableManager.getOutputFromHDFSByJobId("e1ad7bb0-522e-456a-859d-2eab1df448de", "e1ad7bb0-522e-456a-859d-2eab1df448de", Integer.MAX_VALUE).getVerboseMsgStream();
        BufferedReader reader = new BufferedReader(new InputStreamReader(verboseMsgStream, Charset.defaultCharset()))) {
        String line;
        StringBuilder sampleData = new StringBuilder();
        while ((line = reader.readLine()) != null) {
            if (sampleData.length() > 0) {
                sampleData.append('\n');
            }
            sampleData.append(line);
        }
        sampleLog = sampleData.toString();
    }
    String[] actualLines = StringUtils.splitByWholeSeparatorPreserveAllTokens(sampleLog, "\n");
    Assert.assertTrue(Arrays.deepEquals(exceptLines, actualLines));
    String verboseMsg = executableManager.getOutputFromHDFSByJobId("e1ad7bb0-522e-456a-859d-2eab1df448de", "e1ad7bb0-522e-456a-859d-2eab1df448de", 100).getVerboseMsg();
    String[] actualVerboseMsgLines = StringUtils.splitByWholeSeparatorPreserveAllTokens(verboseMsg, "\n");
    ArrayList<String> exceptLinesL = Lists.newArrayList(exceptLines);
    exceptLinesL.add("================================================================");
    Assert.assertTrue(Sets.newHashSet(exceptLinesL).containsAll(Sets.newHashSet(actualVerboseMsgLines)));
}

