    assertEquals(2, chromosomeSet.size());
    BitSet representation3 = new BitSet();
    representation3.set(12);
    chromosomeSet.add(new BitsChromosome(representation3, benefitPolicy, helper1));
    assertEquals(2, chromosomeSet.size());
}

