@Test
public void testCollectQueryScanRowsAndTime() {
    KylinConfig config = KylinConfig.getInstanceFromEnv();
    try (KylinConfig.SetAndUnsetThreadLocalConfig autoUnset = KylinConfig.setAndUnsetThreadLocalConfig(config)) {
        config.setProperty("kylin.query.big-query-source-scan-rows-threshold", "100000000");
        BigQueryThresholdUpdater.resetBigQueryThreshold();
        int n = 1000;
        for (int i = 0; i < n; i++) {
            long duration = new Random().nextInt(10000) + KapConfig.getInstanceFromEnv().getBigQuerySecond() * 1000;
            if (i == n - 1) {
                BigQueryThresholdUpdater.setLastUpdateTime(System.currentTimeMillis() - KapConfig.getInstanceFromEnv().getBigQueryThresholdUpdateIntervalSecond() * 1000);
            }
            BigQueryThresholdUpdater.collectQueryScanRowsAndTime(new Random().nextInt(10000), KapConfig.getInstanceFromEnv().getBigQuerySourceScanRowsThreshold() - 1);
            BigQueryThresholdUpdater.collectQueryScanRowsAndTime(duration, KapConfig.getInstanceFromEnv().getBigQuerySourceScanRowsThreshold() + 1);
        }
        long collectScanRows = KapConfig.getInstanceFromEnv().getBigQuerySourceScanRowsThreshold() + 1;
        await().atMost(10, TimeUnit.SECONDS).untilAsserted(() -> Assert.assertEquals(collectScanRows, BigQueryThresholdUpdater.getBigQueryThreshold()));
    }
}

