@Test
public void testTimeInRange() {
    // Test 1: Data range within partition range
    String[] dataRange1 = { "2023-01-05", "2023-01-10" };
    List<String[]> partitionRange1 = Arrays.asList(new String[] { "2023-01-01", "2023-01-15" }, new String[] { "2022-12-01", "2023-02-01" });
    assertTrue("Data range should be within partition range", DataRangeUtils.timeInRange(dataRange1, partitionRange1, "yyyy-MM-dd"));
    // Test 2: Data range outside partition range
    String[] dataRange2 = { "2023-01-05", "2023-01-10" };
    List<String[]> partitionRange2 = Arrays.asList(new String[] { "2023-01-11", "2023-01-15" }, new String[] { "2023-01-16", "2023-01-20" });
    assertFalse("Data range should be outside partition range", DataRangeUtils.timeInRange(dataRange2, partitionRange2, "yyyy-MM-dd"));
    // Test 3: Invalid data format
    String[] dataRange3 = { "2023-0105", "2023-0110" };
    assertFalse("Data range with invalid format should return false", DataRangeUtils.timeInRange(dataRange3, partitionRange1, "yyyy-MM-dd"));
    // Test 4: Invalid data range (start after end)
    String[] dataRange4 = { "2023-01-10", "2023-01-05" };
    assertFalse("Invalid data range (start after end) should return false", DataRangeUtils.timeInRange(dataRange4, partitionRange1, "yyyy-MM-dd"));
    // Test 5: Null or empty inputs
    assertFalse("Null data range should return false", DataRangeUtils.timeInRange(null, partitionRange1, "yyyy-MM-dd"));
    assertFalse("Empty data range should return false", DataRangeUtils.timeInRange(new String[] {}, partitionRange1, "yyyy-MM-dd"));
    assertFalse("Null partition range should return false", DataRangeUtils.timeInRange(dataRange1, null, "yyyy-MM-dd"));
    assertFalse("Empty partition range should return false", DataRangeUtils.timeInRange(dataRange1, Collections.emptyList(), "yyyy-MM-dd"));
    assertFalse("Empty format string should return false", DataRangeUtils.timeInRange(dataRange1, partitionRange1, ""));
}

