@Test
public void testInternalTableLoadingJobResponse() {
    KylinConfig conf = KylinConfig.getInstanceFromEnv();
    NTableMetadataManager manager = NTableMetadataManager.getInstance(conf, "default");
    InternalTableManager internalManager = InternalTableManager.getInstance(conf, "default");
    InternalTableLoadingJob job = new InternalTableLoadingJob();
    job.setProject("default");
    job.setParam("startTime", "10001");
    job.setParam("endTime", "10002");
    ExecutableResponse response = ExecutableResponse.create(job, null);
    Assert.assertEquals(10001L, response.getDataRangeStart());
    Assert.assertEquals(10002L, response.getDataRangeEnd());
    job.setParam("incrementalBuild", "false");
    response = ExecutableResponse.create(job, null);
    Assert.assertEquals(Long.MAX_VALUE, response.getDataRangeEnd());
    job.setParam("incrementalBuild", "true");
    job.setParam("deletePartition", "true");
    response = ExecutableResponse.create(job, null);
    Assert.assertEquals(Long.MAX_VALUE, response.getDataRangeEnd());
    TableDesc originTable = manager.getTableDesc("DEFAULT.TEST_KYLIN_FACT");
    internalManager.createInternalTable(new InternalTableDesc(originTable));
    job.setParam(NBatchConstants.P_TABLE_NAME, originTable.getIdentity());
    response = ExecutableResponse.create(job, null);
    Assert.assertTrue(response.isTargetSubjectError());
    internalManager.updateInternalTable(originTable.getIdentity(), copyForWrite -> copyForWrite.setLocation(copyForWrite.generateInternalTableLocation()));
    response = ExecutableResponse.create(job, null);
    Assert.assertFalse(response.isTargetSubjectError());
    Assert.assertEquals(originTable.getIdentity(), response.getTargetSubject());
}

@Test
public void testCheckMultiPartitionBuildParam() {
    NDataModel model = mock(NDataModel.class);
    IncrementBuildSegmentParams params = mock(IncrementBuildSegmentParams.class);
    // Not a multi-partition model, no need check
    when(model.isMultiPartitionModel()).thenReturn(false);
    modelBuildService.checkMultiPartitionBuildParam(model, params);
    // Test throwing JOB_CREATE_CHECK_MULTI_PARTITION_EMPTY
    when(model.isMultiPartitionModel()).thenReturn(true);
    when(params.isNeedBuild()).thenReturn(true);
    when(params.getMultiPartitionValues()).thenReturn(new ArrayList<>());
    try {
        modelBuildService.checkMultiPartitionBuildParam(model, params);
    } catch (Exception e) {
        assertTrue(e instanceof KylinException);
        assertEquals(JOB_CREATE_CHECK_MULTI_PARTITION_EMPTY.getCodeMsg(), e.getLocalizedMessage());
    }
    // Test throwing 1st JOB_CREATE_CHECK_MULTI_PARTITION_ABANDON
    when(model.isMultiPartitionModel()).thenReturn(true);
    when(params.isNeedBuild()).thenReturn(false);
    List<String[]> partitionValues = new ArrayList<>();
    partitionValues.add(new String[0]);
    when(params.getMultiPartitionValues()).thenReturn(partitionValues);
    try {
        modelBuildService.checkMultiPartitionBuildParam(model, params);
    } catch (Exception e) {
        assertTrue(e instanceof KylinException);
        assertEquals(JOB_CREATE_CHECK_MULTI_PARTITION_ABANDON.getCodeMsg(), e.getLocalizedMessage());
    }
    // Test throwing 2nd JOB_CREATE_CHECK_MULTI_PARTITION_ABANDON
    when(model.isMultiPartitionModel()).thenReturn(true);
    when(params.isNeedBuild()).thenReturn(true);
    partitionValues = new ArrayList<>();
    partitionValues.add(new String[] { "p1" });
    when(params.getMultiPartitionValues()).thenReturn(partitionValues);
    // mock column size
    LinkedList<String> columns = mock(LinkedList.class);
    MultiPartitionDesc multiPartitionDesc = mock(MultiPartitionDesc.class);
    when(model.getMultiPartitionDesc()).thenReturn(multiPartitionDesc);
    when(multiPartitionDesc.getColumns()).thenReturn(columns);
    when(columns.size()).thenReturn(2);
    try {
        modelBuildService.checkMultiPartitionBuildParam(model, params);
    } catch (Exception e) {
        assertTrue(e instanceof KylinException);
        assertEquals(JOB_CREATE_CHECK_MULTI_PARTITION_ABANDON.getCodeMsg(), e.getLocalizedMessage());
    }
}

@Test
public void testMergeSegment() {
    String project = getProject();
    val dfId = new String("741ca86a-1f13-46da-a59f-95fb68615e3a");
    val dfManager = NDataflowManager.getInstance(getTestConfig(), project);
    // remove exist segment
    indexDataConstructor.cleanSegments(dfId);
    // first segment
    long start = SegmentRange.dateToLong("2010-01-01");
    long end = SegmentRange.dateToLong("2010-02-01");
    SegmentRange segmentRange = new SegmentRange.TimePartitionedSegmentRange(start, end);
    val dataSegment1 = indexDataConstructor.addSegment(dfId, segmentRange, SegmentStatusEnum.READY, null);
    // second segment
    start = SegmentRange.dateToLong("2010-02-01");
    end = SegmentRange.dateToLong("2010-04-01");
    segmentRange = new SegmentRange.TimePartitionedSegmentRange(start, end);
    val dataSegment2 = indexDataConstructor.addSegment(dfId, segmentRange, SegmentStatusEnum.READY, null);
    // third segment
    start = SegmentRange.dateToLong("2010-04-01");
    end = SegmentRange.dateToLong("2010-05-01");
    segmentRange = new SegmentRange.TimePartitionedSegmentRange(start, end);
    val dataSegment3 = indexDataConstructor.addSegment(dfId, segmentRange, SegmentStatusEnum.READY, null);
    try {
        indexDataConstructor.transactionWrap(project, () -> modelBuildService.mergeSegmentsManually(new MergeSegmentParams(project, dfId, new String[] { dataSegment1.getId(), dataSegment3.getId() })));
        Assert.fail();
    } catch (Exception e) {
        Assert.assertTrue(e instanceof KylinException);
        Assert.assertEquals("Can't merge the selected segments, as there are gap(s) in between. Please check and try again.", e.getMessage());
    }
    indexDataConstructor.transactionWrap(project, () -> modelBuildService.mergeSegmentsManually(new MergeSegmentParams(project, dfId, new String[] { dataSegment1.getId(), dataSegment2.getId(), dataSegment3.getId() })));
    val executables = getRunningExecutables("default", "741ca86a-1f13-46da-a59f-95fb68615e3a");
    Assert.assertEquals(1, executables.size());
    Assert.assertEquals(JobTypeEnum.INDEX_MERGE, executables.get(0).getJobType());
    AbstractExecutable job = executables.get(0);
    Assert.assertEquals(1, job.getTargetSegments().size());
    val mergedSegment = dfManager.getDataflow(dfId).getSegment(job.getTargetSegments().get(0));
    Assert.assertEquals(SegmentRange.dateToLong("2010-01-01"), mergedSegment.getSegRange().getStart());
    Assert.assertEquals(SegmentRange.dateToLong("2010-05-01"), mergedSegment.getSegRange().getEnd());
    try {
        //refresh exception
        indexDataConstructor.transactionWrap(project, () -> modelBuildService.mergeSegmentsManually(new MergeSegmentParams(project, dfId, new String[] { dataSegment2.getId() })));
        Assert.fail();
    } catch (KylinException e) {
        Assert.assertEquals("Can't remove, refresh or merge segment \"" + dataSegment2.displayIdName() + "\", as it's LOCKED. Please try again later.", e.getMessage());
    }
    // clear segments
    indexDataConstructor.cleanSegments(dfId);
}

@Test
public void testMergeLoadingSegments() {
    val dfId = new String("741ca86a-1f13-46da-a59f-95fb68615e3a");
    val dfManager = NDataflowManager.getInstance(getTestConfig(), "default");
    val df = dfManager.getDataflow(dfId);
    // remove exist segment
    val update = new NDataflowUpdate(df.getUuid());
    update.setToRemoveSegs(df.getSegments().toArray(new NDataSegment[0]));
    dfManager.updateDataflow(update);
    Segments<NDataSegment> segments = new Segments<>();
    // first segment
    long start = SegmentRange.dateToLong("2010-01-01");
    long end = SegmentRange.dateToLong("2010-02-01");
    SegmentRange segmentRange = new SegmentRange.TimePartitionedSegmentRange(start, end);
    val dataSegment1 = dfManager.appendSegment(df, segmentRange);
    dataSegment1.setStatus(SegmentStatusEnum.NEW);
    dataSegment1.setSegmentRange(segmentRange);
    segments.add(dataSegment1);
    // second segment
    start = SegmentRange.dateToLong("2010-02-01");
    end = SegmentRange.dateToLong("2010-03-01");
    segmentRange = new SegmentRange.TimePartitionedSegmentRange(start, end);
    val dataSegment2 = dfManager.appendSegment(df, segmentRange);
    dataSegment2.setStatus(SegmentStatusEnum.READY);
    dataSegment2.setSegmentRange(segmentRange);
    segments.add(dataSegment2);
    update.setToUpdateSegs(segments.toArray(new NDataSegment[0]));
    dfManager.updateDataflow(update);
    thrown.expect(KylinException.class);
    thrown.expectMessage(SEGMENT_STATUS.getMsg(dataSegment1.displayIdName(), SegmentStatusEnumToDisplay.LOADING.name()));
    modelBuildService.mergeSegmentsManually(new MergeSegmentParams("default", dfId, new String[] { dataSegment1.getId(), dataSegment2.getId() }));
    // clear segments
    update.setToRemoveSegs(df.getSegments().toArray(new NDataSegment[0]));
    dfManager.updateDataflow(update);
}

@Test
public void testRefreshSegmentById_SegmentToRefreshIsLocked_Exception() {
    String project = getProject();
    val modelId = "741ca86a-1f13-46da-a59f-95fb68615e3a";
    NDataflowManager dataflowManager = NDataflowManager.getInstance(getTestConfig(), project);
    val df = dataflowManager.getDataflow(modelId);
    // remove the existed seg
    indexDataConstructor.cleanSegments(modelId);
    long start = SegmentRange.dateToLong("2010-01-01");
    long end = SegmentRange.dateToLong("2010-01-02");
    SegmentRange segmentRange = new SegmentRange.TimePartitionedSegmentRange(start, end);
    NDataSegment dataSegment = indexDataConstructor.addSegment(modelId, segmentRange, null);
    start = SegmentRange.dateToLong("2010-01-02");
    end = SegmentRange.dateToLong("2010-01-03");
    segmentRange = new SegmentRange.TimePartitionedSegmentRange(start, end);
    val dataSegment2 = indexDataConstructor.addSegment(modelId, segmentRange, SegmentStatusEnum.READY, null);
    NDataflowUpdate update = new NDataflowUpdate(df.getUuid());
    update.setToAddOrUpdateLayouts(generateAllDataLayout(getProject(), modelId, Arrays.asList(dataSegment, dataSegment2)));
    EnhancedUnitOfWork.doInTransactionWithCheckAndRetry(() -> NDataflowManager.getInstance(KylinConfig.getInstanceFromEnv(), project).updateDataflow(update), getProject());
    //refresh normally
    indexDataConstructor.transactionWrap(project, () -> modelBuildService.refreshSegmentById(new RefreshSegmentParams(project, "741ca86a-1f13-46da-a59f-95fb68615e3a", new String[] { dataSegment2.getId() })));
    thrown.expect(KylinException.class);
    thrown.expectMessage(String.format(Locale.ROOT, SEGMENT_LOCKED.getErrorMsg().getLocalizedString(), dataSegment2.displayIdName()));
    //refresh exception
    indexDataConstructor.transactionWrap(project, () -> modelBuildService.refreshSegmentById(new RefreshSegmentParams(project, "741ca86a-1f13-46da-a59f-95fb68615e3a", new String[] { dataSegment2.getId() })));
}

