@Test
public void testExportTables() throws Exception {
    // hive data source
    String expectedTableStructure = "CREATE EXTERNAL TABLE default.hive_bigints (   id BIGINT) " + "ROW FORMAT SERDE 'org.apache.hadoop.hive.ql.io.parquet.serde.ParquetHiveSerDe' " + "WITH SERDEPROPERTIES (   'serialization.format' = '1') STORED AS   " + "INPUTFORMAT 'org.apache.hadoop.hive.ql.io.parquet.MapredParquetInputFormat'   " + "OUTPUTFORMAT 'org.apache.hadoop.hive.ql.io.parquet.MapredParquetOutputFormat' " + "LOCATION 'file:/tmp/parquet_data' ";
    sparkSourceService.executeSQL("CREATE EXTERNAL TABLE hive_bigints(id bigint)  STORED AS PARQUET LOCATION '/tmp/parquet_data'");
    String actureTableStructure = sparkSourceService.exportTables("default", new String[] { "hive_bigints" }).getTables().get("hive_bigints");
    Assert.assertEquals(actureTableStructure.substring(0, actureTableStructure.lastIndexOf("TBLPROPERTIES")), expectedTableStructure);
    CatalogTable tableMetadata = SparderEnv.getSparkSession().sessionState().catalog().getTableRawMetadata(new TableIdentifier("hive_bigints", Option.apply("default")));
    Assert.assertTrue(DDLUtils.isHiveTable(tableMetadata));
    // spark datasource
    sparkSourceService.executeSQL("CREATE EXTERNAL TABLE spark_bigints(id bigint) USING PARQUET LOCATION '/tmp/parquet_data_spark'");
    tableMetadata = SparderEnv.getSparkSession().sessionState().catalog().getTableRawMetadata(new TableIdentifier("spark_bigints", Option.apply("default")));
    Assert.assertFalse(DDLUtils.isHiveTable(tableMetadata));
    String sparkDDL = sparkSourceService.exportTables("default", new String[] { "spark_bigints" }).getTables().get("spark_bigints");
    Assert.assertFalse(sparkDDL.isEmpty());
    Assert.assertTrue(StringUtils.containsIgnoreCase(sparkDDL, "USING PARQUET"));
    // delta datasource
    sparkSourceService.executeSQL("CREATE EXTERNAL TABLE delta_bigints(id bigint) USING DELTA LOCATION '/tmp/delta_data_spark'");
    tableMetadata = SparderEnv.getSparkSession().sessionState().catalog().getTableRawMetadata(new TableIdentifier("delta_bigints", Option.apply("default")));
    Assert.assertFalse(DDLUtils.isHiveTable(tableMetadata));
    String deltaDDL = sparkSourceService.exportTables("default", new String[] { "delta_bigints" }).getTables().get("delta_bigints");
    Assert.assertFalse(deltaDDL.isEmpty());
    Assert.assertTrue(StringUtils.containsIgnoreCase(deltaDDL, "USING DELTA"));
    // view
    sparkSourceService.executeSQL("CREATE VIEW view_bigints as select id from default.spark_bigints");
    String viewDDL = DdlOperation.collectDDL(TableIdentifier.apply("view_bigints"), "show create view default.view_bigints");
    Assert.assertFalse(StringUtils.isEmpty(viewDDL));
}

