    Assert.assertEquals("LENGTH(CONCAT(CAST(INSTR(CAST(" + SELLER_ID_COLUMN + " AS VARCHAR), '0') AS VARCHAR), 'll'))", computedColumns.get(1).getExpression().trim());
    Assert.assertEquals("INTEGER", computedColumns.get(1).getDatatype());
    Assert.assertEquals("SPLIT_PART(CONCAT(SUBSTRING(`TEST_KYLIN_FACT`.`LSTG_FORMAT_NAME`, 1), '-apache-kylin'), '-', 1)", computedColumns.get(2).getInnerExpression().trim());
    Assert.assertEquals("SPLIT_PART(CONCAT(SUBSTRING(" + FORMAT_COLUMN_NAME_COLUMN + " FROM 1), '-apache-kylin'), '-', 1)", computedColumns.get(2).getExpression().trim());
    Assert.assertEquals("VARCHAR", computedColumns.get(2).getDatatype());
    Assert.assertEquals("SPLIT_PART(UPPER(SUBSTRING(`TEST_KYLIN_FACT`.`LSTG_FORMAT_NAME`, 1)), 'A', 1)", computedColumns.get(3).getInnerExpression().trim());
    Assert.assertEquals("SPLIT_PART(UPPER(SUBSTRING(" + FORMAT_COLUMN_NAME_COLUMN + " FROM 1)), 'A', 1)", computedColumns.get(3).getExpression().trim());
    Assert.assertEquals("VARCHAR", computedColumns.get(3).getDatatype());
}

