@Test
public void testPushDownForced() throws Exception {
    KylinConfig.getInstanceFromEnv().setProperty(PUSHDOWN_RUNNER_KEY, "org.apache.kylin.query.pushdown.PushDownRunnerSparkImpl");
    KylinConfig.getInstanceFromEnv().setProperty(PUSHDOWN_ENABLED, "true");
    KylinConfig.getInstanceFromEnv().setProperty("kylin.query.pushdown.converter-class-names", "org.apache.kylin.query.util.RestoreFromComputedColumn,org.apache.kylin.query.util.SparkSQLFunctionConverter");
    String prjName = "tdvt";
    // timstampDiff
    String sql = "SELECT {fn TIMESTAMPDIFF(SQL_TSI_DAY,{d '1900-01-01'},\"CALCS\".\"DATE0\")} AS \"TEMP_Test__2048215813__0_\"\n" + "FROM \"CALCS\" \"CALCS\"\n" + "GROUP BY {fn TIMESTAMPDIFF(SQL_TSI_DAY,{d '1900-01-01'},\"CALCS\".\"DATE0\")}";
    val resultForced = pushDownSql(prjName, sql, 0, 0, null, true);
    Assert.assertNotNull(resultForced);
    //test for error when  execption is null and is not forced
    try {
        pushDownSql(prjName, sql, 0, 0, null, false);
        Assert.fail();
    } catch (Exception e) {
        Throwable rootCause = Throwables.getRootCause(e);
        Assert.assertTrue(rootCause instanceof IllegalArgumentException);
    }
    //test for error when  pushdown turn off, and force to push down
    try {
        KylinConfig.getInstanceFromEnv().setProperty(PUSHDOWN_ENABLED, "false");
        Assert.assertFalse(KylinConfig.getInstanceFromEnv().isPushDownEnabled());
        pushDownSql(prjName, sql, 0, 0, null, true);
        Assert.fail();
    } catch (Exception e) {
        Assert.assertTrue(e instanceof KylinException);
        Assert.assertEquals(((KylinException) e).getErrorCode(), QueryErrorCode.INVALID_PARAMETER_PUSH_DOWN.toErrorCode());
        Assert.assertEquals(MsgPicker.getMsg().getDisablePushDownPrompt(), Throwables.getRootCause(e).getMessage());
    } finally {
        KylinConfig.getInstanceFromEnv().setProperty(PUSHDOWN_ENABLED, "true");
    }
}

