@Test
public void testIntersectCountQuery() throws Exception {
    /*
        Source table: USER_ID, AGE, CITY, TAG
        TAG value split by "|"
        
        group by key: 20,Shanghai
        
        rich, 2
        tall, 1
        handsome, 2
        ====================================
        
        group by key: 19,Beijing
        
        rich, 1
        tall, 2
        handsome, 1
        ====================================
        
        group by key: 18,Shenzhen
        
        rich, 1
        tall, 1
        handsome, 1
        * */
    fullBuild("c9ddd37e-c870-4ccf-a131-5eef8fe6cb7e");
    KylinConfig config = KylinConfig.getInstanceFromEnv();
    populateSSWithCSVData(config, getProject(), SparderEnv.getSparkSession());
    String query1 = "select AGE, CITY, " + "intersect_count(USER_ID, TAG, array['rich','tall','handsome']) " + "from TEST_INTERSECT_COUNT group by AGE, CITY";
    List<String> r1 = ExecAndComp.queryModel(getProject(), query1).collectAsList().stream().map(row -> row.toSeq().mkString(",")).collect(Collectors.toList());
    Assert.assertEquals("18,Shenzhen,0", r1.get(0));
    Assert.assertEquals("19,Beijing,0", r1.get(1));
    Assert.assertEquals("20,Shanghai,1", r1.get(2));
    String query2 = "select AGE, CITY, intersect_count(USER_ID, TAG, array['rich']) " + "from TEST_INTERSECT_COUNT group by AGE, CITY";
    List<String> r2 = ExecAndComp.queryModel(getProject(), query2).collectAsList().stream().map(row -> row.toSeq().mkString(",")).collect(Collectors.toList());
    Assert.assertEquals("18,Shenzhen,1", r2.get(0));
