/**
 * A - B - D - C(c2)
 *   \
 *    C
 * <p>
 * index agg [C2.C_CUSTKEY, SUM(C2.C_CUSTKEY)]  ==> index based on A B D C
 * index table [C.*] ==> A C
 * index agg C ==> A C
 */
@Test
public void getRelatedTablesSnowModelTest() {
    String sql = "SELECT C2.C_CUSTKEY, SUM(C2.C_CUSTKEY) \n" + "FROM SSB.P_LINEORDER A\n" + "  LEFT JOIN SSB.DATES B ON A.LO_ORDERDATE = B.D_DATEKEY\n" + "  LEFT JOIN SSB.CUSTOMER C ON A.LO_CUSTKEY = C.C_CUSTKEY\n" + "  LEFT JOIN SSB.LINEORDER D ON B.D_DATEKEY = D.LO_ORDERDATE\n" + "  LEFT JOIN SSB.CUSTOMER C2 ON D.LO_CUSTKEY = C2.C_CUSTKEY\n" + "  GROUP BY C2.C_CUSTKEY ORDER BY C2.C_CUSTKEY";
    String sql2 = "SELECT C.* \n" + "FROM SSB.P_LINEORDER  A\n" + "  LEFT JOIN SSB.DATES B ON A.LO_ORDERDATE = B.D_DATEKEY\n" + "  LEFT JOIN SSB.CUSTOMER C ON A.LO_CUSTKEY = C.C_CUSTKEY\n" + "  LEFT JOIN SSB.LINEORDER D ON B.D_DATEKEY = D.LO_ORDERDATE" + "  LEFT JOIN SSB.CUSTOMER C2 ON D.LO_CUSTKEY = C2.C_CUSTKEY\n";
    String sql3 = "SELECT C.C_CUSTKEY, SUM(C.C_CUSTKEY*2) \n" + "FROM SSB.P_LINEORDER  A\n" + "  LEFT JOIN SSB.DATES B ON A.LO_ORDERDATE = B.D_DATEKEY\n" + "  LEFT JOIN SSB.CUSTOMER C ON A.LO_CUSTKEY = C.C_CUSTKEY\n" + "  LEFT JOIN SSB.LINEORDER D ON B.D_DATEKEY = D.LO_ORDERDATE\n" + "  LEFT JOIN SSB.CUSTOMER C2 ON D.LO_CUSTKEY = C2.C_CUSTKEY\n" + "  GROUP BY C.C_CUSTKEY ORDER BY C.C_CUSTKEY";
    // prepare an origin model
    AbstractContext smartContext = AccelerationUtil.runWithSmartContext(kylinConfig, getProject(), new String[] { sql, sql2, sql3 }, true);
    String modelId = smartContext.getModelContexts().get(0).getTargetModel().getUuid();
    NDataModel originModel = NDataModelManager.getInstance(getTestConfig(), getProject()).getDataModelDesc(modelId);
    indexPlanManager.updateIndexPlan(originModel.getId(), copyForWrite -> {
        val newRule = new RuleBasedIndex();
        newRule.setIndexPlan(copyForWrite);
        newRule.setDimensions(Lists.newArrayList(1));
        NAggregationGroup group1 = null;
        try {
            group1 = JsonUtil.readValue(//
            "{\n" + //
            "        \"includes\": [1],\n" + //
            "        \"measures\": [100000,100001],\n" + //
            "        \"select_rule\": {\n" + //
            "          \"hierarchy_dims\": [],\n" + //
            "          \"mandatory_dims\": [],\n" + //
            "          \"joint_dims\": []\n" + "        }\n" + "}", NAggregationGroup.class);
        } catch (IOException e) {
            // do nothing
        }
        newRule.setAggregationGroups(Lists.newArrayList(group1));
        copyForWrite.setRuleBasedIndex(newRule);
    });
    IndexDependencyParser parser = new IndexDependencyParser(originModel);
    IndexPlan indexPlan = indexPlanManager.getIndexPlan(originModel.getId());
    Assert.assertEquals(4, indexPlan.getAllLayouts().size());
    indexPlan.getAllLayouts().forEach(layoutEntity -> {
        List<String> relatedTables = parser.getRelatedTables(layoutEntity);
        if (IndexEntity.isAggIndex(layoutEntity.getIndexId())) {
            if (relatedTables.size() == 2) {
                Assert.assertEquals("SSB.CUSTOMER", relatedTables.get(0));
            } else {
                Assert.assertEquals(4, relatedTables.size());
                Assert.assertEquals("SSB.CUSTOMER", relatedTables.get(0));
            }
        } else {
            Assert.assertEquals(2, relatedTables.size());
            Assert.assertEquals("SSB.CUSTOMER", relatedTables.get(0));
        }
    });
}

