@Test
public void testPreferAggIndexEnabled() throws SqlParseException {
    overwriteSystemProp("kylin.query.use-tableindex-answer-non-raw-query", "true");
    String modelId = "acfde546-2cc9-4eec-bc92-e3bd46d4e2ee";
