        NLayoutCandidate layoutCandidate = QueryLayoutChooser.selectLayoutCandidate(dataflow, dataflow.getQueryableSegments(), olapContext.getSQLDigest());
        Assert.assertNotNull(layoutCandidate);
        Assert.assertTrue(layoutCandidate.getLayoutEntity().getIndex().isTableIndex());
    }
}

