@Test
public void testPushDownQuery() throws Exception {
    Class.forName("org.h2.Driver");
    overwriteSystemProp("kylin.query.pushdown.runner-class-name", "org.apache.kylin.query.pushdown.PushDownRunnerJdbcImpl");
    overwriteSystemProp("kylin.query.pushdown-enabled", "true");
    overwriteSystemProp("kylin.query.pushdown.cache-enabled", "true");
    overwriteSystemProp("kylin.query.cache-threshold-duration", "0");
    // Load H2 Tables (inner join)
    Connection h2Connection = DriverManager.getConnection("jdbc:h2:mem:db_default", "sa", "");
    H2Database h2DB = new H2Database(h2Connection, getTestConfig(), "default");
    h2DB.loadAllTables();
    overwriteSystemProp("kylin.query.pushdown.jdbc.url", "jdbc:h2:mem:db_default;SCHEMA=`DEFAULT`");
    overwriteSystemProp("kylin.query.pushdown.jdbc.driver", "org.h2.Driver");
    overwriteSystemProp("kylin.query.pushdown.jdbc.username", "sa");
    overwriteSystemProp("kylin.query.pushdown.jdbc.password", "");
    final PrepareSqlRequest sqlRequest = new PrepareSqlRequest();
    sqlRequest.setProject("Default");
    String queryFileName = "src/test/resources/query/sql_pushdown.sql";
    File sqlFile = new File(queryFileName);
    String sql = KylinTestBase.getTextFromFile(sqlFile);
    sqlRequest.setSql(sql);
    // get h2 query result for comparison
    Statement statement = h2Connection.createStatement();
    ResultSet resultSet = statement.executeQuery(sql);
    mockMvc.perform(MockMvcRequestBuilders.post("/api/query").contentType(MediaType.APPLICATION_JSON).content(JsonUtil.writeValueAsString(sqlRequest)).header("User-Agent", "Chrome/89.0.4389.82 Safari/537.36").accept(MediaType.parseMediaType(HTTP_VND_APACHE_KYLIN_JSON))).andExpect(MockMvcResultMatchers.status().isOk()).andExpect(MockMvcResultMatchers.jsonPath("$.data.results[0].length()").value(resultSet.getMetaData().getColumnCount())).andExpect(MockMvcResultMatchers.jsonPath("$.data.pushDown").value(true)).andDo(MockMvcResultHandlers.print()).andReturn();
    // push down can not hit cache because the cache is expired by default
    mockMvc.perform(MockMvcRequestBuilders.post("/api/query").contentType(MediaType.APPLICATION_JSON).content(JsonUtil.writeValueAsString(sqlRequest)).header("User-Agent", "Chrome/89.0.4389.82 Safari/537.36").accept(MediaType.parseMediaType(HTTP_VND_APACHE_KYLIN_JSON))).andExpect(MockMvcResultMatchers.status().isOk()).andExpect(MockMvcResultMatchers.jsonPath("$.data.results[0].length()").value(resultSet.getMetaData().getColumnCount())).andExpect(MockMvcResultMatchers.jsonPath("$.data.pushDown").value(true)).andExpect(MockMvcResultMatchers.jsonPath("$.data.engineType").value(QueryContext.PUSHDOWN_RDBMS)).andExpect(MockMvcResultMatchers.jsonPath("$.data.storageCacheUsed").value(false)).andDo(MockMvcResultHandlers.print()).andReturn();
    h2DB.dropAll();
    h2Connection.close();
}

