@Test
public void testUpdateIndexPlanWithToBeDelete() {
    val id = "89af4ee2-2cdb-4b07-b39e-4c29856309aa";
    val indexPlanManager = NIndexPlanManager.getInstance(KylinConfig.getInstanceFromEnv(), "default");
    val origin = indexPlanManager.getIndexPlan(id);
    var aggregationGroup = getNAggregationGroup(new Integer[] { 100000 });
    val saved = indexPlanService.updateRuleBasedCuboid("default", UpdateRuleBasedCuboidRequest.builder().project("default").modelId(id).isLoadData(true).aggregationGroups(Lists.<NAggregationGroup>newArrayList(aggregationGroup)).build()).getFirst();
    Assert.assertEquals(origin.getAllLayouts().size() + 3, saved.getAllLayouts().size());
    val dfManager = NDataflowManager.getInstance(KylinConfig.getInstanceFromEnv(), "default");
    val readySegs = dfManager.getDataflow(id).getSegments(SegmentStatusEnum.READY, SegmentStatusEnum.WARNING);
    val last = readySegs.getLatestReadySegment().getSegDetails();
    List<NDataLayout> lists = Lists.newArrayList(last.getLayouts());
    List<Long> toAddLayout = new ArrayList<>();
    saved.getRuleBasedIndex().getLayoutIdMapping().forEach(layoutId -> {
        if (saved.getLayoutEntity(layoutId).getDimsIds().size() > 1) {
            toAddLayout.add(layoutId);
        }
    });
    dfManager.updateDataflowDetailsLayouts(readySegs.getLatestReadySegment(), Collections.emptyList(), toAddLayout);
    indexPlanManager.updateIndexPlan(id, copyForWrite -> {
        copyForWrite.markIndexesToBeDeleted(copyForWrite.getId(), saved.getRuleBaseLayouts().stream().filter(layoutEntity -> layoutEntity.getColOrder().size() == 3).collect(Collectors.toSet()));
    });
    aggregationGroup = getNAggregationGroup(new Integer[] { 100000, 100005 });
    var res = indexPlanService.updateRuleBasedCuboid("default", UpdateRuleBasedCuboidRequest.builder().project("default").modelId(id).isLoadData(true).aggregationGroups(Lists.<NAggregationGroup>newArrayList(aggregationGroup)).build()).getFirst();
    Assert.assertEquals(1, res.getToBeDeletedIndexes().size());
    aggregationGroup = getNAggregationGroup(new Integer[] { 100000 });
    res = indexPlanService.updateRuleBasedCuboid("default", UpdateRuleBasedCuboidRequest.builder().project("default").modelId("89af4ee2-2cdb-4b07-b39e-4c29856309aa").isLoadData(true).aggregationGroups(Lists.<NAggregationGroup>newArrayList(aggregationGroup)).build()).getFirst();
    Assert.assertEquals(0, res.getToBeDeletedIndexes().size());
}

