    val oldLayoutId = indexPlanManager.getIndexPlan(BASIC_MODEL).getAllLayouts().stream().filter(l -> l.getColOrder().containsAll(indexCol)).findFirst().map(LayoutEntity::getId).orElse(-1L);
    // modify expression of cc TEST_KYLIN_FACT.NEST5
    val originCC = request.getComputedColumnDescs().stream().filter(c -> ("NEST5").equals(c.getColumnName())).findFirst();
    Assert.assertTrue(originCC.isPresent());
    ComputedColumnDesc cc = originCC.get();
    cc.setExpression(cc.getExpression() + "+1");
