    expectedEx.expect(new BaseMatcher() {

        @Override
        public void describeTo(Description description) {
        }

        @Override
        public boolean matches(Object item) {
            if (!(item instanceof BadModelException)) {
                return false;
            }
            BadModelException ccException = (BadModelException) item;
            return BadModelException.CauseType.SAME_NAME_DIFF_EXPR == ccException.getCauseType() && ccException.getAdvise().equals("\"TEST_KYLIN_FACT\".\"PRICE\" * \"TEST_KYLIN_FACT\".\"ITEM_COUNT\"") && ccException.getConflictingModel().equals("nmodel_basic_inner") && ccException.getBadCC().equals("TEST_KYLIN_FACT.DEAL_AMOUNT") && ccException.getMessage().equals("The name of computed column 'TEST_KYLIN_FACT.DEAL_AMOUNT' has already been used in " + "model 'nmodel_basic_inner', and the expression is " + "'\"TEST_KYLIN_FACT\".\"PRICE\" * \"TEST_KYLIN_FACT\".\"ITEM_COUNT\"'. " + "Please modify the expression to keep consistent, or use a different name.");
        }
    });
    modelService.getManager(NDataModelManager.class, "default").updateDataModelDesc(deserialized);
    // TODO should use modelService.updateModelAndDesc("default", deserialized);
}

