    TableDesc tableDesc = tableMetadataManager.getTableDesc("DEFAULT.TEST_KYLIN_FACT");
    ColumnDesc[] columns = tableDesc.getColumns();
    List<ColumnDesc> colList = Lists.newArrayList(columns);
