    }
    segmentConfigRequest.getVolatileRange().setVolatileRangeNumber(1);
    segmentConfigRequest.getRetentionRange().setRetentionRangeNumber(-1);
    try {
        projectService.updateSegmentConfig(project, segmentConfigRequest);
        Assert.fail();
    } catch (Exception e) {
        Assert.assertTrue(e instanceof KylinException);
        Assert.assertTrue(e.getMessage().contains("No valid value for 'retention_range_number'." + " Please set an integer 'x' to specify the retention threshold. The system will " + "only retain the segments in the retention threshold (x years before the last data time). "));
