    }
    {
        String formattedValue = ReflectionTestUtils.invokeMethod(SegmentPruningRule.class, "checkAndReformatDateType", "2023-02-03 12:00:00", segmentTs, new DataType("timestamp", 0, 0));
        Assertions.assertEquals("2023-02-03 12:00:00", formattedValue);
    }
    {
        String formattedValue = ReflectionTestUtils.invokeMethod(SegmentPruningRule.class, "checkAndReformatDateType", "2023-02-03 12:00:00", segmentTs, new DataType("varchar", 0, 0));
        Assertions.assertEquals("2023-02-03 12:00:00", formattedValue);
    }
    {
        String formattedValue = ReflectionTestUtils.invokeMethod(SegmentPruningRule.class, "checkAndReformatDateType", "2023-02-03 12:00:00", segmentTs, new DataType("string", 0, 0));
