    }
    {
        String formattedValue = ReflectionTestUtils.invokeMethod(SegmentPruningRule.class, "checkAndReformatDateType", "2023-02-03 12:00:00", segmentTs, new DataType("integer", 0, 0));
        Assertions.assertEquals("2023-02-03 12:00:00", formattedValue);
    }
    {
        String formattedValue = ReflectionTestUtils.invokeMethod(SegmentPruningRule.class, "checkAndReformatDateType", "2023-02-03 12:00:00", segmentTs, new DataType("bigint", 0, 0));
