    u1cr1.setColumn(u1c1);
    AclTCR.Row u1r1 = new AclTCR.Row();
    AclTCR.RealRow u1rr1 = new AclTCR.RealRow();
    u1rr1.addAll(Arrays.asList("11", "22", "33"));
    u1r1.put("ITEM_COUNT", u1rr1);
    u1cr1.setRow(u1r1);
    AclTCR.ColumnRow u1cr2 = new AclTCR.ColumnRow();
