    String sql = "   --  CubePriority(kylin_1,kylin_2,kylin_1,kylin_3)   \n" + "SELECT * FROM KYLIN_SALES as KYLIN_SALES\n" + " -- CubePriority(kylin_4,kylin_5)   \n -- CubePriority(kylin_4,kylin_5)\n";
