@Test
void testMoreTimestampAddAndDiff() throws SqlParseException {
    NDataModel model = NDataModelManager.getInstance(KylinConfig.getInstanceFromEnv(), "tdvt").getDataModelDesc("e6a4c3bb-6391-4995-9e33-cc24ac5a155b");
    {
        String sql = "select sum((int1-int2)/(int1+int2)) as c1,\n" + "sum((int1-int2)/timestampdiff(second, time0, time1) ) as c2,\n" + "sum(timestampdiff(second, time0, time1)/timestampdiff(second, timestampadd(year,1, time1), time1)) as c3\n" + "from tdvt.calcs";
        checkReplaceAggDateFunctionsCc(model, sql);
    }
    // case 2
    {
        String sql = "select sum(case when int0 > 0 then timestampdiff(day, time0, time1) end) as ab\n" + "  from tdvt.calcs as calcs";
        checkReplaceAggDateFunctionsCc(model, sql);
    }
    // case 3
    {
        String sql = "select sum(case when time0 <> time1 then (int2-int1)/timestampdiff(second, time0, time1) * 60\n" + //
        "    else (int2 - int1)/ timestampdiff(second, time1, datetime0)*60 end)\n" + "from tdvt.calcs";
        checkReplaceAggDateFunctionsCc(model, sql);
    }
    // case 4
    {
        String sql = "select case when int0 > 0 then timestampdiff(second, time0, time1) else 0 end\n" + "from tdvt.calcs\n" + "group by case when int0 > 0 then timestampdiff(second, time0, time1) else 0 end\n" + "order by case when int0 > 0 then timestampdiff(second, time0, time1) else 0 end";
        checkReplaceGroupByDateFunctionsCc(model, sql);
    }
    // case 5
    {
        String sql = "select case when int0 > 100 then timestampdiff(second, time0, time1)\n" + "                when int0 > 50 then timestampdiff(minute, time0, time1)\n" + "                when int0 > 0 then timestampdiff(hour, time0, time1) else null end\n" + "from tdvt.calcs group by case when int0 > 100 then timestampdiff(second, time0, time1)\n" + "                when int0 > 50 then timestampdiff(minute, time0, time1)\n" + "                when int0 > 0 then timestampdiff(hour, time0, time1) else null end";
        checkReplaceGroupByDateFunctionsCc(model, sql);
    }
    // case 6
    {
        String sql = "select case when int0 > 10 then sum(timestampdiff(second, time0, time1)) else sum(timestampdiff(minute, time0, time1)) end\n" + "from tdvt.calcs group by int0";
        checkReplaceAggDateFunctionsCc(model, sql);
    }
    // case 7
    {
        String sql = "with ca as(select time0 as t0, time1, datetime0 from tdvt.calcs)\n" + "select sum(timestampdiff(minute, ca.time1, ca.t0)), ca.datetime0\n" + "from ca group by ca.datetime0";
        checkReplaceAggDateFunctionsCc(model, sql);
    }
    // case 8
    {
        String sql = "select sum(tmp.ab) from (\n" + "  select sum(timestampdiff(second, time0, time1)/timestampdiff(second, timestampadd(year,1, time1), time1)) as ab\n" + "  from tdvt.calcs as calcs) tmp";
        checkReplaceAggDateFunctionsCc(model, sql);
    }
    // case 9
    {
        String sql = "select sum(timestampdiff(minute, time1, time0)), datetime0, time1, time0\n" + //
        "from tdvt.calcs group by datetime0, time1, time0\n" + //
        "union\n" + "select max(timestampdiff(minute, time1, time0)), datetime0, time1, time0\n" + "from tdvt.calcs group by datetime0, time1, time0";
        List<OlapContext> olapContexts = OlapContextTestUtil.getOlapContexts("tdvt", sql, true, true);
        for (OlapContext olapContext : olapContexts) {
            OlapContextTestUtil.rewriteComputedColumns(model, olapContext);
            for (FunctionDesc aggregation : olapContext.getAggregations()) {
                String paramList = aggregation.getParameters().stream().map(param -> param.getColRef().getCanonicalName()).collect(Collectors.joining(","));
                // assert the cc has been replaced
                Assertions.assertTrue(paramList.startsWith("TDVT.CALCS.CC_AUTO_"));
            }
        }
    }
    // case 10
    {
        String sql = "select max(timestampdiff(second, time0, cast(datetime1 as timestamp)))\n" + //
        " - min(timestampdiff(second, time0, cast(datetime1 as timestamp)))\n" + "from tdvt.calcs";
        checkReplaceAggDateFunctionsCc(model, sql);
    }
    // case 11: window function
    {
        String sql = "select num1, max(TIMESTAMPADD(SQL_TSI_DAY, 1, TIMESTAMP '1970-01-01 10:01:01')) MAXTIME,\n" + "      max(TIMESTAMPADD(SQL_TSI_DAY, 1, TIMESTAMP '1970-01-01 10:01:01')) over() MAXTIME1\n" + //
        "from tdvt.calcs where num1 > 0\n" + //
        "group by num1\n" + "order by TIMESTAMPADD(SQL_TSI_DAY,1, TIMESTAMP '1970-01-01 10:01:01')";
        checkReplaceAggDateFunctionsCc(model, sql);
    }
    // case 11: window function
    {
        String sql = //
        "select num1, max(TIMESTAMPADD(SQL_TSI_DAY, 1, time0)) over() MAXTIME1\n" + //
        "from tdvt.calcs\n" + //
        "where num1 > 0\n" + //
        "group by num1, time0\n" + "order by TIMESTAMPADD(SQL_TSI_DAY,1, TIMESTAMP'1970-01-01 10:01:01')";
        checkReplaceAggDateFunctionsCc(model, sql);
    }
}

