    String sql = "select   ACCOUNT_ID   ,     ACCOUNT_ID     +    1  ,  x'a+ b'  ,X'c *     d', ACCOUNT_ID+2,count(*) from " + "KYLIN_ACCOUNT " + "group   by  ACCOUNT_ID  " + "limit  400   ";
    String sql1 = "select   ACCOUNT_ID   ,  \n   ACCOUNT_ID   \r  +    1  ,  x'a+ b'  ,X'c *     d',\f ACCOUNT_ID+2,count(*) from " + "KYLIN_ACCOUNT " + "group   by  ACCOUNT_ID  " + "limit  400   ";
    String sql2 = "select   ACCOUNT_ID   ,  \n\n   ACCOUNT_ID   \r\r  +    1  ,  x'a+ b'  ,X'c *     d',\f ACCOUNT_ID+2,count(*) from " + "KYLIN_ACCOUNT " + "group   by  ACCOUNT_ID  " + "limit  400   ";
    String sql3 = "select \n  ACCOUNT_ID   ,  \n\n\r\t   ACCOUNT_ID   \r\r  +    1  ,  x'a+ b'  ,X'c *     d',\f ACCOUNT_ID+2,count(*) from " + "KYLIN_ACCOUNT " + "group   by  ACCOUNT_ID  " + "limit  400   ";
    testBinary(sql);
    testBinary(sql1);
    testBinary(sql2);
    testBinary(sql3);
}

