@Test
public void testSqlsFormat() {
    List<String> sqls = Lists.newArrayList("select * from A", "select A.a, B.b from A join B on A.a2=B.b2", "Select sum(a), b from A group by b", "select * from A as c limit 1");
    // see https://olapio.atlassian.net/browse/KE-42029
    // Calcite 1.30 SQL format changes, not exceptions do not need to be adjusted
    List<String> expectedFormattedSqls = Lists.newArrayList("SELECT *\nFROM \"A\"", "SELECT \"A\".\"A\",\n  \"B\".\"B\"\nFROM \"A\"\n  INNER JOIN \"B\" ON \"A\".\"A2\" = \"B\".\"B2\"", "SELECT SUM(\"A\"),\n  \"B\"\nFROM \"A\"\nGROUP BY \"B\"", "SELECT *\nFROM \"A\" AS \"C\"\nLIMIT 1");
    val formated = queryService.format(sqls);
    Assert.assertEquals(sqls.size(), formated.size());
    for (int n = 0; n < sqls.size(); n++) {
        Assert.assertEquals(expectedFormattedSqls.get(n), formated.get(n));
    }
}

