@Test
public void testQueryWithAdminPermission() {
    QueryService queryService = Mockito.spy(new QueryService());
    SQLRequest sqlRequest = new SQLRequest();
    sqlRequest.setExecuteAs("ADMIN");
    sqlRequest.setProject("default");
    sqlRequest.setSql("select 1");
    overwriteSystemProp("kylin.query.security.acl-tcr-enabled", "true");
    // role admin
    {
        Mockito.doReturn(new QueryContext.AclInfo("ADMIN", Sets.newHashSet("ROLE_ADMIN"), false)).when(queryService).getExecuteAclInfo("default", "ADMIN");
        Assert.assertTrue(queryService.isACLDisabledOrAdmin("default", queryService.getExecuteAclInfo("default", "ADMIN")));
    }
    // project admin permission
    {
        Mockito.doReturn(new QueryContext.AclInfo("ADMIN", Sets.newHashSet("FOO"), true)).when(queryService).getExecuteAclInfo("default", "ADMIN");
        Assert.assertTrue(queryService.isACLDisabledOrAdmin("default", queryService.getExecuteAclInfo("default", "ADMIN")));
    }
    // normal user
    {
        Mockito.doReturn(new QueryContext.AclInfo("ADMIN", Sets.newHashSet("FOO"), false)).when(queryService).getExecuteAclInfo("default", "ADMIN");
        Assert.assertFalse(queryService.isACLDisabledOrAdmin("default", queryService.getExecuteAclInfo("default", "ADMIN")));
    }
    overwriteSystemProp("kylin.query.security.acl-tcr-enabled", "false");
    // acl disabled
    {
        Mockito.doReturn(new QueryContext.AclInfo("ADMIN", Sets.newHashSet("FOO"), false)).when(queryService).getExecuteAclInfo("default", "ADMIN");
        Assert.assertTrue(queryService.isACLDisabledOrAdmin("default", queryService.getExecuteAclInfo("default", "ADMIN")));
    }
}

