    // currently, column part_dt's cardinality < 2000 && tans_id's > 2000
    getTestConfig().setProperty("kylin.smart.conf.rowkey.uhc.min-cardinality", "2000");
    String[] sqls = new String[] { "select part_dt, lstg_format_name, trans_id from kylin_sales where part_dt = '2012-01-01'", "select part_dt, trans_id from kylin_sales where trans_id = 100000", "select part_dt, lstg_format_name, trans_id from kylin_sales", "select part_dt, lstg_format_name, trans_id from kylin_sales where trans_id = 100000 group by part_dt, lstg_format_name, trans_id" };
