@Test
public void testProposedLayoutConsistency() {
    List<String> sqlList = Lists.newArrayList("select test_kylin_fact.order_id, lstg_format_name\n" + "from test_kylin_fact left join test_order on test_kylin_fact.order_id = test_order.order_id\n" + "order by test_kylin_fact.order_id, lstg_format_name\n", "select lstg_format_name, seller_id, sum(price)\n" + "from test_kylin_fact left join test_account on test_kylin_fact.seller_id = test_account.account_id\n" + //
    "group by lstg_format_name, seller_id\n" + "order by lstg_format_name, seller_id\n", "select lstg_format_name, sum(price)\n" + "from test_kylin_fact left join test_account on test_kylin_fact.seller_id = test_account.account_id\n" + "inner join test_country on test_account.account_country = test_country.country\n" + //
    "group by lstg_format_name\n" + "order by lstg_format_name\n", "select lstg_format_name, test_kylin_fact.leaf_categ_id, sum(price)\n" + "from test_kylin_fact inner join test_category_groupings on test_kylin_fact.leaf_categ_id = test_category_groupings.leaf_categ_id\n" + "group by lstg_format_name, test_kylin_fact.leaf_categ_id\n" + "order by lstg_format_name, test_kylin_fact.leaf_categ_id\n", "select account_country\n" + "from test_account inner join test_country on test_account.account_country = test_country.country\n" + //
    "order by account_country\n");
    val context = AccelerationUtil.runWithSmartContext(getTestConfig(), getProject(), sqlList.toArray(new String[0]), true);
    final Map<String, AccelerateInfo> secondRoundMap = context.getAccelerateInfoMap();
    final Set<String> secondRoundProposedColOrders = collectColOrders(secondRoundMap.values());
    // Suggested layouts should be independent of the order of input sqls
    {
        // shuffle and propose
        Collections.shuffle(sqlList);
        val context1 = AccelerationUtil.runWithSmartContext(getTestConfig(), getProject(), sqlList.toArray(new String[0]), true);
        final Map<String, AccelerateInfo> thirdRoundMap = context1.getAccelerateInfoMap();
        final Set<String> thirdRoundProposedColOrders = collectColOrders(thirdRoundMap.values());
        Assert.assertEquals(secondRoundProposedColOrders, thirdRoundProposedColOrders);
    }
    // Suggested layouts should be independent of modeling by a single batch or multi-batches
    {
        List<String> batchOne = sqlList.subList(0, sqlList.size() / 2);
        val context1 = AccelerationUtil.runWithSmartContext(getTestConfig(), getProject(), batchOne.toArray(new String[0]), true);
        final Map<String, AccelerateInfo> batchOneMap = context1.getAccelerateInfoMap();
        List<String> batchTwo = sqlList.subList(sqlList.size() / 2, sqlList.size());
        val context2 = AccelerationUtil.runWithSmartContext(getTestConfig(), getProject(), batchTwo.toArray(new String[0]), true);
        final Map<String, AccelerateInfo> batchTwoMap = context2.getAccelerateInfoMap();
        Set<String> batchProposedColOrders = Sets.newHashSet();
        batchProposedColOrders.addAll(collectColOrders(batchOneMap.values()));
        batchProposedColOrders.addAll(collectColOrders(batchTwoMap.values()));
        Assert.assertEquals(secondRoundProposedColOrders, batchProposedColOrders);
    }
}

