    NDataModel model2 = modelManager.getDataModelDesc(modelId);
    Assert.assertEquals(2, model2.getJoinTables().size());
    Assert.assertEquals(117, model2.getAllNamedColumns().size());
    // proposing new index
    normSql = "select test_order.order_id,buyer_id,max(price) from test_order " + "left join test_kylin_fact on test_order.order_id=test_kylin_fact.order_id " + "group by test_order.order_id,buyer_id,LSTG_FORMAT_NAME";
