    exprTypes.put("TEST_MEASURE.PRICE6 + 1", "INTEGER");
    exprTypes.put("TEST_MEASURE.PRICE7 + 1", "INTEGER");
    exprTypes.put("TEST_MEASURE.PRICE5 * TEST_MEASURE.PRICE6 + TEST_MEASURE.PRICE7", "SMALLINT");
