    exprTypes.put("SPLIT(TEST_MEASURE.NAME1, '[ABC]', 2)", "array<string>");
    AtomicInteger ccId = new AtomicInteger(0);
    List<ComputedColumnDesc> newCCs = exprTypes.keySet().stream().map(expr -> {
