public void testGetDataParser() throws Exception {
    String json1 = "{\"cust_no\":\"343242\",\"windowDate\":\"2021-06-01 00:00:00\"," + "\"windowDateLong\":\"1625037465002\",\"msg_type\":\"single\",\"msg_type1\":\"old\"," + "\"msg_type2\":\"jily\",\"msg_type3\":\"pandora\",\"age\":\"32\",\"bal1\":21,\"bal2\":12,\"bal3\":13,\"bal4\":15,\"bal5\":22}";
    String json2 = "{\"cust_no\":\"343242\",\"windowDate\":\"2021-06-01 00:00:00\"," + "\"windowDateLong\":\"1625037465002\",\"msg_type\":\"single\",\"msg_type1\":\"old\"," + "\"msg_type2\":\"jily\",\"msg_type3\":\"pandora\",\"age\":\"32\",\"bal1\":21,\"bal2\":12,\"bal3\":13,\"bal4\":15,\"bal5\":22";
    val dataParser = AbstractDataParser.getDataParser(DEFAULT_PARSER_NAME, Thread.currentThread().getContextClassLoader());
    Assert.assertNotNull(dataParser);
    dataParser.before();
    dataParser.after(Maps.newHashMap());
    Assert.assertTrue(dataParser.defineDataTypes().isEmpty());
    dataParser.process(StandardCharsets.UTF_8.encode(json1));
    dataParser.process(null);
    ByteBuffer encode = StandardCharsets.UTF_8.encode(json2);
    Assert.assertThrows(JsonParseException.class, () -> dataParser.process(encode));
    ClassLoader contextClassLoader = Thread.currentThread().getContextClassLoader();
    Assert.assertThrows(IllegalStateException.class, () -> AbstractDataParser.getDataParser(null, contextClassLoader));
    Assert.assertThrows(IllegalStateException.class, () -> AbstractDataParser.getDataParser("java.lang.String", contextClassLoader));
}

